function act(type,data={}){return new Promise((resolve,reject)=>{if(!session){reject(new Error('No estás en una sala.'));return;}queue.push({type,data,resolve,reject});nextPulse=0;pump();});}
function fire(type,data={}){act(type,data).catch(e=>toast(e.message));}
