  const death=s.deathNotices?.at(-1);if(death&&death.id!==lastDeathNoticeId){lastDeathNoticeId=death.id;if(now()-death.time<9000)roleNotice(`EL ENCHUFE · ${death.name} ha muerto en la planta ${death.floor}.`);}
