$('mapBtn').addEventListener('click',toggleMap);$('closeMap').addEventListener('click',()=>show('mapOverlay',false));
function openModal(title,html,kind='help'){if((kind==='help'||kind==='appearance')&&modalKind)closeModal();modalKind=kind;keys.clear();$('modalTitle').textContent=title;$('modalContent').innerHTML=html;$('taskError').textContent='';$('modalEyebrow').textContent=kind==='help'?'MANUAL DE LA EXPEDICIÓN':kind==='appearance'?'IDENTIDAD DEL EXPLORADOR':'ESTACIÓN DE TRABAJO';show('modal',true);}
function closeModal(cancel=true){if(modalKind==='appearance')wardrobeAbort.abort();if(taskCleanup){taskCleanup();taskCleanup=null;}const wasTask=modalKind==='task'||modalKind==='repair';taskTimers.forEach(clearTimeout);taskTimers=[];activeTask=null;modalKind=null;show('modal',false);show('ventDock',false);if(cancel&&wasTask&&session)fire('cancel');}
$('closeModal').addEventListener('click',()=>closeModal());
$('helpBtn').addEventListener('click',()=>openModal('Cómo jugar',`<div class="help-list"><div><b>Junta a tu clase.</b> Crea una sala y comparte el código. Mínimo 4 personas para un impostor, 7 para dos. El líder configura y empieza.</div><div><b>Explora las plantas elegidas.</b> WASD o flechas. E para tareas, botón rojo, reparación y escaleras. M abre el plano con pestañas de planta. Cada tarea indica su ubicación.</div><div><b>Tripulantes.</b> Completad las tareas o expulsad a todos los impostores. Los documentos se recogen en el Despacho de Vaquero y se entregan en Dirección. Los espectros pueden atravesar paredes y seguir trabajando.</div><div><b>Impostores.</b> Q elimina a un tripulante cercano después de la recarga que configure el líder. V abre una rejilla cercana: entra, viaja entre las tres rejillas de tu circuito y sale donde elijas. No hay conexiones entre los cuatro circuitos. No puedes matar ni moverte mientras estás oculto. El ingeniero también puede usarlas.</div><div><b>Roles adicionales.</b> Empollón: N abre una libreta privada incluso durante reuniones. Ingeniero: V permite viajar por alcantarillas entre plantas. Delegado: selecciona a alguien y usa el pulgar decisivo una vez; acertar gana y fallar te expulsa. El enchufe: conoce el nombre y planta de cada muerte. Creyente: recibe señales de cuatro emojis de los fantasmas; al morir, estos usan 1–4 en la barra inferior. Los roles son únicos y a veces no se asigna ninguno. Impostor Fantasma: F lo oculta 15 s. Copiador Boss: F copia a otro vivo 30 s. F termina el efecto; ambos se recargan 90 s.</div><div><b>Reuniones.</b> R denuncia un cadáver cercano. El botón rojo está en Recepción (P0), o en Profesores (P1) si se juega solo allí; cada jugador dispone de una reunión. Los jugadores vivos pueden moverse en la clase de reunión. Los fantasmas permanecen quietos. El chat aparece sobre los personajes. Selecciona un jugador con sombra verde, confirma con ✓ o cancela con ×. También puedes pulsar Skip. Empate y Skip no expulsan.</div><div><b>Sabotajes.</b> El botón ⚡ permite elegir entre seis averías. Se reparan en los paneles de las plantas activas. En dos plantas la emergencia cooperativa requiere dos personas en paneles distintos, con menos de 8 s de diferencia. Las puertas se abren a los 18 s; el sabotaje sigue activo hasta reparar los paneles. Si pasan 90 s sin reparar, gana el impostor. La recarga es de 112,5 s.</div><div><b>Conexión.</b> Recargar recupera tu sesión. Si pierdes conexión durante la partida, tu plaza se conserva; en la espera caduca tras 30 s. Dos profesores patrullan cada partida. En los pasillos te persiguen y, si te alcanzan, te retienen 30 s en Expulsados; entrar en un aula te protege. El plano escolar es orientativo y está basado en la plantilla recibida.</div></div>`));
$('editAppearance').addEventListener('click',()=>{const p=state.me;openModal('Vestuario de clase',`<div class="wardrobe-preview">${robotSVG(p)}</div><label class="field-label" for="editName">Nombre</label><input id="editName" maxlength="18" value="${esc(p.name)}"><label class="field-label" for="editColor">Color de identidad</label><select id="editColor">${COLOR_NAMES.map((n,i)=>`<option value="${i}" ${i===p.color?'selected':''} ${state.roster.some(q=>q.id!==p.id&&q.color===i)?'disabled':''}>${n}</option>`).join('')}</select><nav class="wardrobe-tabs" aria-label="Secciones del vestuario"><button type="button" data-wardrobe-tab="clothes" class="selected" aria-pressed="true">Ropa</button><button type="button" data-wardrobe-tab="face" aria-pressed="false">Personaje</button><button type="button" data-wardrobe-tab="extras" aria-pressed="false">Accesorios</button></nav><div class="wardrobe-fields">${Object.entries(wardrobe).map(([id,choices])=>`<label data-wardrobe-group="${wardrobeSection(id)}" ${wardrobeSection(id)==='clothes'?'':'hidden'}>${wardrobeLabels[id]}<select data-wardrobe="${id}">${choices.map((n,i)=>`<option value="${i}" ${i===(p[id]??0)?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`).join('')}</div><button id="saveAppearance" class="primary wide">Guardar ropa →</button>`,'appearance');
 $('modalContent').querySelector('.wardrobe-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-wardrobe-tab]');if(!b)return;$('modalContent').querySelectorAll('[data-wardrobe-tab]').forEach(t=>{const chosen=t===b;t.classList.toggle('selected',chosen);t.setAttribute('aria-pressed',String(chosen));});$('modalContent').querySelectorAll('[data-wardrobe-group]').forEach(label=>label.hidden=label.dataset.wardrobeGroup!==b.dataset.wardrobeTab);});
 const read=()=>{const result={name:$('editName').value,color:Number($('editColor').value)};document.querySelectorAll('[data-wardrobe]').forEach(el=>result[el.dataset.wardrobe]=Number(el.value));return result;};
 $('modalContent').addEventListener('input',()=>{$('modalContent').querySelector('.wardrobe-preview').innerHTML=robotSVG(read());},{once:false,signal:wardrobeSignal()});
 $('saveAppearance').addEventListener('click',async()=>{const p=read();try{await act('profile',p);appearance=p;$('playerName').value=p.name;for(const id of Object.keys(wardrobe))$(id).value=p[id];updateAppearance();closeModal(false);}catch(e){$('taskError').textContent=e.message;}});
});
function wardrobeSignal(){wardrobeAbort.abort();wardrobeAbort=new AbortController();return wardrobeAbort.signal;}
document.addEventListener('keydown',e=>{const k=e.key.toLowerCase(),typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(k==='escape'&&!$('notebookOverlay').hidden){e.preventDefault();show('notebookOverlay',false);$(state?.phase==='meeting'?'meetingWorld':'world').focus();return;}if(typing)return;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)&&state)e.preventDefault();if(k==='escape'){if(!$('notebookOverlay').hidden)show('notebookOverlay',false);else if(!$('mapOverlay').hidden)show('mapOverlay',false);else if(modalKind)closeModal();return;}if(k==='n'&&!e.repeat&&state?.me.specialRole==='nerd'){e.preventDefault();toggleNotebook();return;}if(k==='m'&&!e.repeat&&!modalKind){toggleMap();return;}if(!e.repeat&&/^[1-4]$/.test(k)&&state&&!state.me.alive&&!modalKind&&$('mapOverlay').hidden&&$('notebookOverlay').hidden&&state.believerAlive&&now()>=state.me.spiritReady){const emoji=state.spiritEmojis?.[Number(k)-1];if(emoji){e.preventDefault();fire('spirit',{emoji});return;}}keys.add(k);if(!e.repeat&&['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'].includes(k)){inputDirty=true;nextPulse=0;pump();}if(e.repeat||modalKind||!$('mapOverlay').hidden)return;if(k==='e')use();if(k==='v'&&!$('ventBtn').disabled)$('ventBtn').click();if(k==='f'&&!$('abilityBtn').disabled)$('abilityBtn').click();if(k==='q'&&!$('killBtn').disabled)$('killBtn').click();if(k==='r'&&!$('reportBtn').disabled)$('reportBtn').click();});
document.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keys.delete(k);if(['w','a','s','d','arrowup','arrowleft','arrowdown','arrowright'].includes(k)){inputDirty=true;nextPulse=0;pump();}});window.addEventListener('blur',()=>{keys.clear();inputDirty=true;nextPulse=0;pump();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();inputDirty=true;nextPulse=0;pump();}});

function openTask(task){if(!task)return;openInteractive(task,'task');}
function openRepair(repair){openInteractive(repair,'repair');}
function openInteractive(task,kind){
 if(taskCleanup)taskCleanup();openModal(task.label,'',kind);activeTask=task;
 taskCleanup=mountTask($('modalContent'),task,{tone,submit:async solution=>{
  const delay=Math.max(0,task.start+task.minDuration-now()+100);if(delay)await new Promise(resolve=>{taskTimers.push(setTimeout(resolve,delay));});
  if(activeTask!==task)throw new Error('La tarea se ha cerrado.');
  const result=await act(kind==='task'?'finishTask':'finishRepair',{id:task.id,solution});closeModal(false);cue('task');
  toast(result.carrying?'Documentos recogidos. Llévalos a Dirección (P0).':result.retryCoop?'Necesitáis dos personas distintas en los dos paneles.':kind==='task'?'Tarea completada.':state.sabotage?.kind==='emergency'?'Panel confirmado: la otra persona tiene 8 s.':'Panel reparado. Comprueba el otro.');
 }});
}

function frame(time){const dt=Math.min(.05,(time-lastTime)/1000);lastTime=time;if(!state){drawHero($('hero'),time);drawAvatar($('avatar'),appearance,time);}else{const axis=input(),map=state.phase==='meeting'?MEETING:state.phase==='lobby'?LOBBY:mapFor(state.me.floor,state.sabotage),ghost=state.phase!=='lobby'&&!state.me.alive;if(['lobby','game','meeting'].includes(state.phase)){const px=local.x,py=local.y;move(state.phase==='game'&&state.me.alive&&state.me.expelledUntil>now()?detentionMap(map):map,local,axis.x,axis.y,dt,ghost,state.config.speed);recordMotion(axis,dt);if((axis.x||axis.y)&&!ghost&&Math.hypot(local.x-px,local.y-py)>.25&&time-lastStep>290){lastStep=time;tone(95+(Math.floor(time/290)%2)*20,.035,'triangle',.013);}}local.input=axis;for(const p of [...state.players,...(state.teachers||[])]){if(p.id===state.me.id)continue;const at=remoteAt(remoteSamples.get(p.id),now(),p.detained?detentionMap(map):map,state.config.speed);if(at)rendered.set(p.id,at);}for(const id of rendered.keys())if(!remoteSamples.has(id))rendered.delete(id);if(state.phase==='meeting'){state.selectedVote=voteSelection;drawWorld($('meetingWorld'),state,local,rendered,cam,dt,time);}else drawWorld($('world'),state,local,rendered,cam,dt,time);if(!$('mapOverlay').hidden&&time-lastUi>100){drawMiniMap($('mapCanvas'),state,local,mapFloor);updateMapFloorButtons();}if(time-lastUi>100){lastUi=time;updateClocks();}}
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
try{session=JSON.parse(sessionStorage.getItem('sanagus.session')||'null');}catch{}if(session){show('menu',false);show('game',true);show('networkBanner',true);$('networkBanner').textContent='Recuperando tu sesión… Puedes pulsar Salir para volver al menú.';$('roomCode').textContent=session.code;nextPulse=0;pump();}
